    EXAMS_FOOD.g2.push({ name:"Đề thi thử số 9", questions: (function(){ var A=[];
    A.push(Q("gak",null,"f2kotei",3,"工程管理者が行う「教育の効果確認」の方法として、正しいものはどれですか。",["実際に作業をさせて確認したり、テストや観察で理解度を見る","教育した回数を数えるだけでよい","感想を聞くだけでよい","確認は不要である"],0,"Hiệu quả đào tạo đo bằng việc người học LÀM ĐƯỢC đúng chuẩn khi quan sát thực tế hoặc qua kiểm tra — số buổi đào tạo không chứng minh được năng lực."));
    A.push(Q("gak",null,"f2kotei",3,"「見て分かる管理」が進んだ状態として、正しいものはどれですか。",["正常か異常かが、現場の表示や状態で誰でも判断できる","表示が多ければ多いほどよい","管理者だけが分かる表示でよい","表示はなくてよい"],0,"Quản lý trực quan đạt khi bất kỳ ai đứng tại hiện trường cũng phân biệt được bình thường/bất thường qua nhãn, vạch giới hạn, bảng trạng thái — không cần hỏi quản lý."));
    A.push(Q("gak",null,"f2kotei",3,"作業者の「やる気」を高める管理者の行動として、適切なものはどれですか。",["よい作業や改善を認めて伝え、成長の機会を作る","失敗だけを強く責める","結果に関心を持たない","他の人と比較してけなす"],0,"Ghi nhận công khai việc làm tốt và cải tiến, tạo cơ hội phát triển kỹ năng — động lực bền vững đến từ được công nhận và tiến bộ, không phải từ sợ bị trách mắng."));
    A.push(Q("gak",null,"f2kotei",3,"会議（ミーティング）を効果的にする工夫として、正しいものはどれですか。",["目的と時間を決め、決まったことと担当・期限を記録する","目的なく長く話す","決まったことは記録しない","参加者は発言してはいけない"],0,"Họp hiệu quả có mục đích rõ, giới hạn thời gian, và đầu ra là quyết định kèm người phụ trách + thời hạn được ghi lại — quản lý công đoạn chủ trì họp đầu ca theo nguyên tắc này."));
    A.push(Q("gak",null,"f2kotei",3,"工程の「変更点管理」で、変更後に行うこととして、正しいものはどれですか。",["変更後の製品や状態を、通常より注意して確認する期間を設ける","変更したら終わりである","確認は通常と同じでよい","変更は記録しなくてよい"],0,"Sau thay đổi (người, máy, nguyên liệu, phương pháp) phải có giai đoạn tăng cường xác nhận sản phẩm đầu và thông số — phần lớn lỗi hàng loạt xuất hiện ngay sau điểm thay đổi."));
    A.push(Q("gak",null,"f2eisei",3,"食品工場の「手洗い場」の設備として必要なものはどれですか。",["温水、石けん、消毒液、ペーパータオルなどが使える状態にある","水だけがあればよい","タオルは共用でよい","石けんはなくてよい"],0,"Điểm rửa tay phải luôn sẵn: nước ấm, xà phòng, dung dịch khử trùng, khăn giấy dùng một lần và thùng rác không dùng tay mở. Thiếu vật tư là lỗi quản lý phải xử lý ngay khi điểm検."));
    A.push(Q("gak",null,"f2eisei",3,"「二次汚染」を防ぐ考え方として、正しいものはどれですか。",["汚染された手や器具、作業着などから食品へ汚染が移らないようにする","二次汚染は防げない","器具は洗わなくてよい","手袋をすれば何を触ってもよい"],0,"Ô nhiễm thứ cấp lây qua trung gian (tay, dụng cụ, đồ bảo hộ, bề mặt) — phòng bằng rửa tay đúng thời điểm, phân dụng cụ theo用途， và vệ sinh bề mặt tiếp xúc theo tần suất quy định."));
    A.push(Q("gak",null,"f2eisei",3,"食品の「中心温度」を測る理由として、正しいものはどれですか。",["一番冷たい（熱が通りにくい）部分が基準に達したかを確認するため","表面の温度だけ見ればよいため","色で判断するため","速く測るため"],0,"Nhiệt độ tâm là điểm nóng lên chậm nhất của thực phẩm — chỉ khi tâm đạt chuẩn (ví dụ 75°C trong 1 phút) mới khẳng định toàn bộ khối thực phẩm được diệt khuẩn đủ."));
    A.push(Q("gak",null,"f2eisei",3,"冷却水や氷の管理で大切なことはどれですか。",["食品に使う氷や水は、飲用に適した衛生的なものを使う","氷はどんな水で作ってもよい","氷は床に置いてよい","氷を素手でつかんでよい"],0,"Đá và nước tiếp xúc thực phẩm phải làm từ nước đạt chuẩn uống được, bảo quản trong thùng sạch có nắp, lấy bằng dụng cụ riêng — đá bẩn là nguồn ô nhiễm thường bị bỏ quên."));
    A.push(Q("gak",null,"f2eisei",3,"食品表示の「一括表示」の確認で大切なことはどれですか。",["名称、原材料、添加物、内容量、期限、保存方法、製造者などが正しく表示されている","デザインがきれいなことだけ","文字が大きいことだけ","色が目立つこと"],0,"Nhãn tổng hợp phải đủ và đúng các hạng mục luật định: tên, nguyên liệu, phụ gia, khối lượng, hạn, cách bảo quản, nhà sản xuất — quản lý công đoạn xác nhận ngay ở sản phẩm đầu ca."));
    A.push(Q("gak",null,"frd",3,"「指差し確認」をする場面として、正しいものはどれですか。",["機械の起動前、条件の変更後、表示の確認など、間違えると重大な場面","すべての作業で常に必要である","急いでいるときは省略する場面","確認が簡単な場面だけ"],0,"Chỉ tay xác nhận dùng ở các điểm sai sót gây hậu quả lớn: trước khởi động máy, sau thay đổi điều kiện, kiểm tra nhãn/thông số — tập trung vào điểm trọng yếu thay vì hình thức mọi nơi."));
    A.push(Q("gak",null,"frd",3,"荷物の持ち上げ作業の基準として、正しい考え方はどれですか。",["重い物は台車や補助具を使い、一人で持つ量には限度を決める","力のある人は無制限に持ってよい","速く持てば腰に負担はない","基準は決めなくてよい"],0,"Nâng vật nặng phải có giới hạn trọng lượng bê tay theo quy định nội bộ (và hướng dẫn của Bộ Y tế Lao động), vượt giới hạn thì dùng xe đẩy hoặc bê hai người — đau lưng là bệnh nghề nghiệp phổ biến nhất cần phòng."));
    A.push(Q("gak",null,"frd",3,"非常口や避難経路の管理として、正しいものはどれですか。",["常に物がなく、すぐ通れる状態に保つ","物を置いても端ならよい","鍵をかけておく","表示はなくてよい"],0,"Lối thoát hiểm phải luôn thông thoáng, cửa mở được từ bên trong, biển chỉ dẫn sáng rõ — kiểm tra lối thoát là hạng mục cố định của tuần tra an toàn."));
    A.push(Q("gak",null,"frd",3,"消火器の管理で大切なことはどれですか。",["場所を表示し、定期的に点検し、使い方を教育する","倉庫の奥にしまう","使い方の教育は不要である","期限が過ぎても使い続ける"],0,"Bình chữa cháy: đặt nơi dễ thấy có biển báo, điểm検 định kỳ (áp suất, hạn), và mọi nhân viên biết cách dùng cơ bản — bình không ai biết dùng thì vô giá trị khi cháy thật."));
    A.push(Q("gak",null,"frd",3,"AED（自動体外式除細動器）の設置場所を従業員に知らせる理由として、正しいものはどれですか。",["心停止のときに、早く使えるかどうかが命に関わるから","飾りのため","設置は法律で禁止されているから","知らせる必要はない"],0,"Máy AED cứu sống người ngừng tim nếu được dùng trong vài phút đầu — mọi nhân viên phải biết vị trí máy và quy trình gọi cấp cứu 119 song song với sơ cứu."));
    A.push(Q("gak",null,"f2hin",4,"「品質コスト」を下げる考え方として、正しいものはどれですか。",["予防と評価に適切に投資し、不良やクレームの失敗コストを大きく減らす","検査をすべてやめてコストをゼロにする","教育費をゼロにする","失敗コストは仕方がないと考える"],0,"Tổng chi phí chất lượng thấp nhất khi đầu tư phòng ngừa hợp lý để cắt giảm mạnh chi phí lỗi (phế phẩm, làm lại, thu hồi, mất khách) — cắt kiểm tra và đào tạo chỉ làm tổng chi phí tăng."));
    A.push(Q("gak",null,"f2hin",4,"検査の「自動化」の利点と注意点として、正しいものはどれですか。",["判定が安定する利点があるが、装置の点検と校正、正しい設定の管理が必要である","自動化すれば管理は不要になる","自動検査は絶対に間違えない","設定は誰でも変えてよい"],0,"Kiểm tra tự động (máy dò kim loại, kiểm tra trọng lượng, camera) cho phán đoán ổn định 24/7, nhưng độ tin cậy phụ thuộc điểm検 bằng mẫu thử, hiệu chuẩn và quản lý quyền thay đổi cài đặt."));
    A.push(Q("gak",null,"f2hin",4,"「外観検査」の基準を明確にする方法として、正しいものはどれですか。",["写真や限度見本で、合格と不合格の境目を具体的に示す","言葉だけで説明する","検査員の感覚に任せる","基準は人によって違ってよい"],0,"Kiểm tra ngoại quan mơ hồ là nguồn tranh cãi và phán đoán lệch: ảnh mẫu và mẫu giới hạn biến tiêu chuẩn thành thứ nhìn thấy được, thống nhất giữa mọi kiểm tra viên."));
    A.push(Q("gak",null,"f2hin",4,"データの集計で「平均」だけを見る問題点として、正しいものはどれですか。",["ばらつきや最大・最小が見えず、異常が隠れることがある","平均は正確なので問題はない","平均だけ見れば十分である","数字は見なくてよい"],0,"Chỉ nhìn trung bình che giấu độ phân tán và giá trị cực đoan: một lô có trung bình đạt vẫn có thể chứa sản phẩm vượt quy cách. Quản lý chất lượng luôn xem trung bình cùng độ lệch và xu hướng."));
    A.push(Q("gak",null,"f2hin",4,"「是正処置」の効果確認として、正しいものはどれですか。",["対策の後、一定期間データを見て、同じ問題が起きていないか確認する","対策を決めた時点で終わりにする","確認は1日だけ行う","効果は確認しなくてよい"],0,"Hiệu quả biện pháp khắc phục phải được xác nhận bằng dữ liệu trong một khoảng thời gian đủ dài (số lô/số ca) — tuyên bố 'đã sửa' ngay sau khi ra biện pháp là chưa hoàn thành."));
    A.push(Q("gak",null,"f2hin",4,"品質に関わる「文書管理」で大切なことはどれですか。",["最新版が現場で使われ、古い版が使われないように管理する","文書は多ければ多いほどよい","古い版も現場に置いておく","文書の版は管理しなくてよい"],0,"Quản lý văn bản: chỉ phiên bản mới nhất có mặt tại hiện trường, bản cũ thu hồi và hủy theo quy định — dùng nhầm quy trình cũ là lỗi hệ thống kinh điển."));
    A.push(Q("gak",null,"f2hin",4,"お客様への「品質情報の提供」で大切なことはどれですか。",["求められた情報（規格、検査結果など）を正確に、早く提供する","情報は出さない方がよい","遅れて提供してよい","一部の情報だけを出す"],0,"Cung cấp thông tin chất lượng cho khách hàng (quy cách, kết quả kiểm tra, chứng nhận) phải chính xác và kịp thời — minh bạch thông tin là nền tảng của quan hệ B2B trong ngành thực phẩm."));
    A.push(Q("gak",null,"f2sei",4,"「生産性」と「効率」の管理で、数字の使い方として正しいものはどれですか。",["目標と実績を比べて、差の原因を調べて改善する","数字は報告のためだけに使う","差があっても原因は調べない","よい数字だけを報告する"],0,"Số liệu quản lý chỉ có giá trị khi được dùng để phân tích chênh lệch và cải tiến — báo cáo chọn lọc số đẹp là hành vi làm méo hệ thống quản lý."));
    A.push(Q("gak",null,"f2sei",4,"原材料の「ロット管理」を生産管理で行う理由として、正しいものはどれですか。",["使用した原材料と製品を結びつけ、在庫と品質の両方を管理するため","ロットは品質だけのものである","在庫とは関係がない","ロット管理は不要である"],0,"Quản lý lô nguyên liệu phục vụ đồng thời: tồn kho chính xác (nhập-xuất theo lô) và truy xuất chất lượng (sản phẩm nào dùng lô nguyên liệu nào) — hai hệ thống phải khớp nhau."));
    A.push(Q("gak",null,"f2sei",4,"生産の「開始前確認」で確認することとして、正しいものはどれですか。",["材料、包材、機械の条件、人員、表示などの準備状態","終わった後の片付けだけ","売上の確認だけ","天気の確認だけ"],0,"Xác nhận trước sản xuất (điểm検 bắt đầu ca): nguyên liệu đúng lô, bao bì đúng phiên bản, thông số máy, nhân lực, mẫu nhãn — phát hiện sai lệch ở phút này rẻ hơn mọi thời điểm khác."));
    A.push(Q("gak",null,"f2sei",4,"「生産調整会議」の目的として、正しいものはどれですか。",["営業、生産、品質などの関係部門で、注文と生産の計画を調整する","生産部門だけで決める会議","会議は形式だけでよい","調整は各部門が別々に行う"],0,"Họp điều phối sản xuất đồng bộ thông tin giữa kinh doanh (đơn hàng), sản xuất (năng lực) và chất lượng (rủi ro) — tránh tình trạng nhận đơn vượt năng lực hoặc sản xuất sai ưu tiên."));
    A.push(Q("gak",null,"f2sei",4,"設備の「予備品（スペアパーツ）」管理で大切なことはどれですか。",["壊れやすい部品や、調達に時間のかかる部品を決めて在庫する","すべての部品を大量に在庫する","予備品は持たなくてよい","部品リストは作らなくてよい"],0,"Linh kiện dự phòng chọn theo hai tiêu chí: tần suất hỏng và thời gian mua — danh mục được rà soát theo lịch sử hỏng hóc, tránh cả thiếu lẫn ứ đọng vốn."));
    A.push(Q("gak",null,"f2sei",4,"「作業の平準化」で作業者への配慮として、正しいものはどれですか。",["重い作業と軽い作業を組み合わせ、負担が偏らないようにする","同じ人に重い作業を続けさせる","負担の偏りは関係がない","若い人だけに重い作業をさせる"],0,"San bằng cũng áp dụng cho gánh nặng con người: luân phiên việc nặng/nhẹ giữa các thành viên để tránh quá tải cục bộ gây đau lưng và tai nạn — vừa là an toàn vừa là công bằng trong nhóm."));
    A.push(Q("gak",null,"f2sei",4,"生産実績を「見える化」する掲示の内容として、正しいものはどれですか。",["計画と実績、不良、停止の理由などを、現場で見える場所に表示する","給料の明細を掲示する","個人の失敗を大きく掲示する","掲示は管理者だけが見る"],0,"Bảng hiển thị hiện trường trình bày kế hoạch-thực tế, lỗi và lý do dừng máy ở mức nhóm/công đoạn — không dùng để bêu tên cá nhân, vì mục đích là cải tiến hệ thống."));
    A.push(Q("gak",null,"f2sha",4,"食品ロス削減のための「需要予測」の改善として、正しいものはどれですか。",["販売データ、天候、行事などの情報を使い、予測の精度を上げる","予測は感覚だけで行う","予測は一度決めたら変えない","データは使わなくてよい"],0,"Dự báo nhu cầu dùng dữ liệu bán hàng quá khứ cộng yếu tố biến động (thời tiết, ngày lễ, sự kiện) và được đối chiếu thực tế mỗi ngày để học dần — giảm cả sản xuất thừa lẫn thiếu hàng."));
    A.push(Q("gak",null,"f2sha",4,"未利用食品の活用方法として、正しいものはどれですか。",["規格外品を加工用原料に使う、フードバンクへ提供するなど、安全を保って活用する","規格外品はすべて捨てるしかない","安全でなくても活用してよい","活用の方法はない"],0,"Thực phẩm chưa được tận dụng (hàng lệch quy cách ngoại quan nhưng an toàn) có thể chuyển làm nguyên liệu chế biến hoặc qua food bank — điều kiện tiên quyết luôn là an toàn được xác nhận."));
    A.push(Q("gak",null,"f2sha",4,"環境ラベル（エコマークなど）の役割として、正しいものはどれですか。",["環境に配慮した製品であることを、消費者に分かりやすく伝える","製品を高く売るためだけの印である","法律で決められた義務表示である","味の良さを示す印である"],0,"Nhãn sinh thái là chứng nhận tự nguyện của bên thứ ba giúp người tiêu dùng nhận biết sản phẩm thân thiện môi trường — doanh nghiệp không được tự in nhãn khi chưa được chứng nhận."));
    A.push(Q("gak",null,"f2sha",4,"職場の「心理的安全性」が大切な理由として、正しいものはどれですか。",["失敗や異常を報告しやすい環境が、問題の早期発見につながるから","何を言ってもよい無法の状態にするため","規律は不要になるため","上司の指示は聞かなくてよいため"],0,"An toàn tâm lý: nhân viên dám báo cáo sai sót và bất thường mà không sợ bị trừng phạt vô lý — điều kiện để hệ thống phát hiện vấn đề sớm. Nó không có nghĩa là bỏ kỷ luật."));
    A.push(Q("gak",null,"f2sha",4,"若い世代や学生への食の情報発信が企業に求められる背景として、正しいものはどれですか。",["食生活の乱れや、食への関心の低下が社会の課題になっているから","広告のためだけである","若い人はお客様ではないから","情報発信は不要である"],0,"Doanh nghiệp thực phẩm tham gia truyền thông về ăn uống lành mạnh vì rối loạn ăn uống và giảm quan tâm tới thực phẩm đang là vấn đề xã hội — đồng thời xây dựng thế hệ người tiêu dùng hiểu biết."));
    A.push(Q("gak",null,"f2sha",4,"企業の「透明性」を高める取り組みとして、正しいものはどれですか。",["工場見学の受け入れや、製造情報の公開などで、事業の内容を社会に伝える","情報はすべて秘密にする","都合のよい情報だけを出す","公開は法律で禁止されている"],0,"Minh bạch qua tham quan nhà máy, công bố thông tin sản xuất và báo cáo CSR giúp xã hội giám sát và tin tưởng doanh nghiệp — che giấu thông tin bất lợi là điều phá hủy minh bạch nhanh nhất."));
    A.push(Q("jitsu","handan","f2eisei",5,"この状況で、正しい対応はどれですか。",["その原材料は使わず、区分して責任者に報告する","においがなければ使ってよい","水で洗えば使える","他のロットと混ぜて使う"],0,"Bao bì nguyên liệu rách hở trong kho nghĩa là nguy cơ ô nhiễm và côn trùng xâm nhập không loại trừ được: tách riêng, không dùng, báo cáo để phán đoán dựa trên loại hàng và thời gian phát hiện.", "倉庫で、原材料の袋が破れて中身が見えているものが見つかりました。"));
    A.push(Q("jitsu","handan","f2eisei",5,"この対応として、正しいものはどれですか。",["作業者を交代させ、手洗いと体調の確認を行い、責任者に報告する","マスクをすれば食品を扱ってよい","本人が平気と言えば続けさせる","他の人に知らせない"],0,"Ho và hắt hơi liên tục là triệu chứng hô hấp có thể phát tán vi khuẩn qua giọt bắn: rời vị trí tiếp xúc thực phẩm, kiểm tra sức khỏe và báo cáo. Khẩu trang không đủ để ở lại vị trí trực tiếp.", "作業者が、咳とくしゃみを繰り返しながら食品を扱っています。"));
    A.push(Q("jitsu","keikaku","f2eisei",5,"温度記録の確認回数として、正しいものはどれですか。",["3台 × 2回 = 6回","3回","2回","確認は不要"],0,"Theo quy định quản lý: mỗi tủ kiểm tra 2 lần/ngày, 3 tủ = 6 lượt ghi nhận mỗi ngày. Quản lý công đoạn dùng lịch này để rà soát hồ sơ cuối ca.", "冷蔵庫が3台あります。決まりでは、1台につき1日2回、温度を測って記録します。"));
    A.push(Q("jitsu","handan","f2eisei",5,"まず行うべきことはどれですか。",["製造を止め、アルコール濃度と器具の状態を確認し、その間の製品を区分する","においがするので問題ないとして続ける","記録だけ書いて続ける","次の休憩で確認する"],0,"Khử trùng cồn không đạt nồng độ quy định tương đương không khử trùng: dừng, kiểm tra lại dung dịch và dụng cụ, tách sản phẩm đã xử lý trong khoảng thời gian nghi ngờ.", "消毒用アルコールの濃度を測ると、決められた濃度より低いことが分かりました。器具の消毒に使っていました。"));
    A.push(Q("jitsu","handan","frd",5,"この状況で、まず行うべきことはどれですか。",["すぐに離れた場所から声をかけ、電源を切って、安全を確認してから助ける","すぐに手で触って助ける","水をかける","そのまま様子を見る"],0,"Người bị điện giật: TUYỆT ĐỐI không chạm trực tiếp khi nguồn chưa cắt (sẽ bị giật theo). Cắt nguồn, gọi cấp cứu, rồi mới tiếp cận sơ cứu.", "作業者が電気設備に触れて、倒れています。手が設備に触れたままです。"));
    A.push(Q("jitsu","handan","frd",5,"この作業者への対応として、正しいものはどれですか。",["すぐに止めさせ、保護メガネを使わせてから作業させる","小さい粉なのでそのまま続けさせる","目をこすらせる","他の作業者にも保護具なしでさせる"],0,"Bụi bay vào mắt và đường hô hấp: dừng việc, trang bị kính bảo hộ và khẩu trang chống bụi theo đánh giá rủi ro của công việc, đồng thời xem xét biện pháp giảm bụi tại nguồn.", "粉を扱う作業で、作業者が保護メガネをしないで作業しています。粉が目に入りそうです。"));
    A.push(Q("jitsu","keikaku","frd",5,"この職場の災害傾向として、正しい判断はどれですか。",["同じ型の災害が繰り返されているので、共通の原因を調べて対策する","毎回違う原因なので対策は不要","件数が少ないので問題ない","記録をやめる"],0,"Ba vụ tai nạn cùng kiểu trong một tháng là tín hiệu hệ thống (thiết bị, quy trình hoặc đào tạo có lỗ hổng chung) — phải phân tích nguyên nhân chung thay vì xử lý từng vụ riêng lẻ.", "1か月の間に、同じ機械で指を切るケガが3件起きました。"));
    A.push(Q("jitsu","keikaku","f2hin",5,"このロットの処置として、正しい計算と判断はどれですか。",["不良率4%で基準を超えるため、ロット全体を区分して責任者の判断を受ける","不良は8個だけなので、そのまま出荷する","もう一度同じ検査をして判断する","平均を取って合格にする"],0,"Tỉ lệ lỗi = 8 ÷ 200 = 4% > chuẩn 3%: theo quy tắc lấy mẫu, kết quả mẫu đại diện cho cả lô — lô bị tách và chờ phán đoán, không kiểm tra lại để tìm kết quả khác.", "抜取検査で200個を調べ、不良品が8個ありました。基準は不良率3%以下です。"));
    A.push(Q("jitsu","handan","f2hin",5,"この対応として、正しいものはどれですか。",["出荷を止め、温度の記録と製品への影響を確認する","1時間だけなので出荷する","お客様には知らせない","記録を書き換える"],0,"Xe vận chuyển lạnh hỏng điều hòa làm đứt chuỗi lạnh: giữ hàng, đối chiếu ghi nhiệt độ hành trình và đo nhiệt độ sản phẩm để đánh giá ảnh hưởng — thời gian 'chỉ 1 giờ' không tự động có nghĩa là an toàn.", "配送中の冷蔵車の温度が、故障で1時間上がっていたことが分かりました。製品は配達先に着いています。"));
    A.push(Q("jitsu","keikaku","f2hin",5,"改善の優先順位として、正しいものはどれですか。",["異物の混入（安全に関わる）を最優先で対策する","包装の軽い傷から対策する","全部を同じ力で対策する","件数の少ないものから対策する"],0,"Nguyên tắc ưu tiên chất lượng: vấn đề liên quan an toàn (dị vật) luôn đứng trước vấn đề ngoại quan, bất kể tần suất — thứ tự này không thay đổi theo Pareto khi an toàn bị đe dọa.", "不良の内訳は、異物の混入2件、包装の軽い傷15件、印刷のかすれ8件でした。"));
    A.push(Q("jitsu","handan","f2hin",5,"この判断として、正しいものはどれですか。",["その原材料は使わず、規格書と現物を確認して責任者に報告する","色が少し違うだけなので使う","他のロットと混ぜて使う","加熱すれば問題ない"],0,"Nguyên liệu khác quy cách (độ ẩm cao hơn) ảnh hưởng trực tiếp chất lượng và hạn dùng sản phẩm: không tự ý dùng, đối chiếu規格書 với kết quả đo và báo cáo để quyết định trả hàng hay xử lý đặc biệt.", "受入検査で、原材料の水分が規格より高い結果が出ました。"));
    A.push(Q("jitsu","keikaku","f2sei",5,"必要な作業者数として、正しいものはどれですか。",["4人","3人","5人","2人"],0,"Nhu cầu: 1.600 ÷ 8 giờ = 200 sản phẩm/giờ ÷ 50 sản phẩm/người/giờ = 4 người.", "8時間で製品1,600個を作ります。作業者1人は1時間に50個作ることができます。"));
    A.push(Q("jitsu","keikaku","f2sei",5,"この設備のチョコ停の影響として、正しい計算はどれですか。",["1日合計30分の停止で、製品150個分の生産が失われている","停止は短いので影響はない","製品への影響は計算できない","30個分の生産が失われている"],0,"Dừng vặt cộng dồn: 3 phút × 10 lần = 30 phút = 0,5 giờ × 300 sản phẩm/giờ = 150 sản phẩm bị mất mỗi ngày — đủ lớn để phải cải tiến như hỏng hóc thật sự.", "設備が1回3分のチョコ停を、1日に10回起こしています。ラインの能力は1時間に300個です。"));
    A.push(Q("jitsu","handan","f2sei",5,"この状況への対応として、正しいものはどれですか。",["在庫を確認し、足りない分は生産計画の調整を責任者と相談する","黙って出荷日を遅らせる","他の得意先の製品を回す","在庫の数字を合わせる"],0,"Thiếu bao bì sát ngày xuất hàng: xác nhận tồn kho thật, tính lượng thiếu và đề xuất điều chỉnh (giao bao bì khẩn, đổi lịch đóng gói) qua cấp trên. Tự ý lấy phần của khách khác gây thiếu dây chuyền.", "出荷の2日前に、包材の在庫が足りないことが分かりました。"));
    A.push(Q("jitsu","keikaku","f2sei",5,"発注する量として、正しいものはどれですか。",["160kg","200kg","120kg","240kg"],0,"Lượng đặt = nhu cầu 200kg − tồn kho 80kg + tồn kho an toàn 40kg = 160kg. Áp dụng nhất quán công thức: nhu cầu − hiện có + an toàn.", "来週、原材料を200kg使います。今の在庫は80kgで、安全在庫は40kgを保つ決まりです。"));
    return A; })() });
